#include <iomanip>
#include <iostream>
#include <sstream>
#include <syncstream>
#include <utility>

int main() {
    std::osyncstream out(std::cout);
    out << "test\n";
    std::ostringstream str_out;
    std::osyncstream{str_out} = std::move(out); // Note that out is emitted here
    std::cout << "str_out = " << std::quoted(str_out.view()) << '\n';
}
